import pandas as pd
import pytest


def in_scope_weight(df: pd.DataFrame) -> float:
    """Total final_weight of in-scope rows."""
    return float(df.loc[df["in_scope"], "final_weight"].sum())


RESPONDENTS = pd.DataFrame(
    {"respondent_id": ["R1", "R2"], "final_weight": [1.0, 3.0], "in_scope": [True, False]}
)


def test_in_scope_weight_skips_out_of_scope():
    assert in_scope_weight(RESPONDENTS) == 1.0

