import pandas as pd
import pytest


@pytest.fixture(scope="module")
def respondents():
    return pd.DataFrame({"id": ["R1", "R2"], "w": [1.0, 3.0]})


def test_cap_weights(respondents):
    respondents.loc[respondents["w"] > 2, "w"] = 2.0
    assert respondents["w"].max() == 2.0


def test_total_weight(respondents):
    assert respondents["w"].sum() == 4.0
